                                              // Publisher Options from the Edit menu,                                                // OR, the user has selected a subscriber                                                // in the document and then selected                                                // Subscriber Options from the Edit menuconst CommandNumber cBorders = 604;				// the user has selected Show/ Hide Borders                                                // from the Edit menuconst CommandNumber cStopAllEditions = 605;		// the user has selected Stop all Editions                                                // from the Edit menu//----------------------------------------------------------------------------------------// Edition Manager command constants//----------------------------------------------------------------------------------------const CommandNumber cCancelPublisher = 606;		// the user canceled this publisherconst CommandNumber cCancelSubscriber = 607;	// the user canceled this subscriber//----------------------------------------------------------------------------------------// miscellaneous constants//----------------------------------------------------------------------------------------const IDType kSectionBehavior = 'sect';const IDType kSubscriberAdornerID = 'subs';const IDType kPublisherAdornerID = 'publ';//----------------------------------------------------------------------------------------// Forward and external class declarations. //----------------------------------------------------------------------------------------class TDesignator;class TFile;class TPublisher;class TSection;class TSectionList;class TSubscriber;class TView;class TEditionDocument;//----------------------------------------------------------------------------------------// TFileBasedDocument//----------------------------------------------------------------------------------------class EXPORT_MA TEditionDocument : public TFileBasedDocument// The TEditionDocument class manages the application's interaction// with the Edition Manager on a per-document basis. Each open application// document having a publisher or subscriber uses one TEditionDocument// object to manage its associated publishers and subscribers. In// addition, TEditionDocument objects are responsible for setting// up the Edition Manager menu items and managing these menu items// by posting commands implemented in specialized subclasses of// TCommand.{	public:	//------------------------------------------------------------------------------------	// constructor/destructor methods	//------------------------------------------------------------------------------------	TEditionDocument(TFile*			itsFile = NULL,					 const OSType	itsScrapType = kNoIdentifier,					 const OSType	editionCreator = kAllQuestionsType_AC);		// Constructor	virtual ~TEditionDocument();		// frees this object	virtual void FreeData();		// frees the fSectionList	//------------------------------------------------------------------------------------	// saving documents	//------------------------------------------------------------------------------------	virtual void Close();		// For the case in which the document's change count = 0, but there are "dirty"        // sections, need to ask the user whether to save the document.	virtual short PoseNewPublishersAlert();		// Warns the user that he is about to close a document that hasn't been saved in        // which he has created a new publisher. The user hasn't modified the document's        // data.	virtual short PoseMultPublishersAlert(TSection* aSection);		// Warns the user that he is creating multiple publishers to the same edition.	virtual short PoseSavingMultPublishersAlert(TSection* aSection);		// Warns the user that he is saving multiple publishers to the same edition.	virtual void Abandon();		// Calls TSection.Delete on all dirty sections.	virtual void DoNeedDiskSpace(TFile* itsFile,										long& dataForkBytes,										long& rsrcForkBytes) const;		// Bytes required to store SAVE file(s) on disk. When called, both parameters are        // set to 0 for you.	virtual void DoWrite(TFile* aFile, bool makingCopy);		// writes out the sections and edition doc settings	virtual void DoWriteSettings(TFile* aFile);		// writes out the edition doc settings (Show/ Hide Border, Stop All Editions)	virtual void DoRead(TFile* aFile, bool forPrinting);		// reads in the sections and edition doc settings	virtual void DoReadSettings(TFile* aFile);		// reads in the edition doc settings (Show/ Hide Border, Stop All Editions)	virtual void DoReadPublisher(TFile* aFile, short theID);		// reads in a given publisher	virtual void DoReadSubscriber(TFile* aFile, short theID);		// reads in a given subscriber	//------------------------------------------------------------------------------------	// Revert	//------------------------------------------------------------------------------------	virtual void RevertDocument();		// Calls Abandon() and then Inherited.	//------------------------------------------------------------------------------------	// Accessors	//------------------------------------------------------------------------------------	virtual void SetSectionBorders(bool state, bool invalidate);		// sets the value of fShowSectionBorders to state and invalidates the document's windows        // if "invalidate" is true	virtual void SetStopAllEditions(bool state);		// sets the value of fStopAllEditions to state and reads in any new subscribers if "state"        // is true	//------------------------------------------------------------------------------------	// menu management methods	//------------------------------------------------------------------------------------	virtual void DoMenuCommand(CommandNumber aCommandNumber);	virtual void DoSetupMenus();	virtual bool CanPublishSelection();	virtual bool CanSubscribe();	//------------------------------------------------------------------------------------	// edition manager support	//------------------------------------------------------------------------------------	virtual void DoAddSectionBehavior(TView* itsView);		// creates and adds a TSectionBehavior to implement the Ed Mgr shortcuts.	virtual void DoNewPublisher();	virtual TPublisher* DoMakePublisher(TDesignator* itsDesignator,											   SectionHandle itsSectionHandle,											   short itsSectionID);	virtual void DoNewPublisherDialog(NewPublisherReply& reply);	virtual void DoMakePreview(TDesignator* itsDesignator,									  FormatType& previewFormat,									  Handle& preview);		virtual void DisposeOfPreview(NewPublisherReply& reply);		// Called from DoNewPublisher.  Default implementation diposes of the view		// if it is of type 'TEXT' or 'PICT'.  Override this method to dispose of		// your own special preview type.	virtual void DoNewSubscriber();	virtual TSubscriber* DoMakeSubscriber(TDesignator* itsDesignator,												 SectionHandle itsSectionHandle,												 short itsSectionID);	virtual void DoNewSubscriberDialog(NewSubscriberReply& reply);	virtual void DoSectionOptions();		// poses the publisher or subscriber options dialog depending on what        // GetSelectedSection returns	virtual FormatType GetPublishPreference();		// return 'PICT' to publish 'PICT' first, return 'TEXT' to publish 'TEXT' first	virtual SignedByte GetSubscriberFormatsMask();	virtual CString_AC GetNextEditionName() const;	virtual void DoPublisherOptions(TPublisher* aPublisher);	virtual void DoPublisherOptionsDialog(SectionOptionsReply& reply);	virtual void DoSubscriberOptions(TSubscriber* aSubscriber);	virtual void DoSubscriberOptionsDialog(SectionOptionsReply& reply);		//------------------------------------------------------------------------------------	// section management	//------------------------------------------------------------------------------------	virtual void AddSection(TSection* aSection);		// adds the section to this document's section list	virtual void AddSectionAndBorder(TSection* aSection);		// adds the section to this document's section list and calls DoAddBorder to add		// its border. This should be used when the view hierarchy has already been		// constructed and we know that have a view to attach the border to.	virtual void CancelSection(TSection* aSection, bool cancel);		// calls aSection->CancelSection(cancel);	virtual TSection* GetSelectedSection();		// This returns the currently selected section, if any. Returns nil if > 1 section        // is currently selected.	virtual short GetUniqueSectRsrcID();		// returns a unique 'sect' resource id for use as both the section ID and as the        // rsrc ID	virtual bool IsSectionSelected(TSection* aSection);		// returns true if the given section is in the user selection	virtual void RemoveSection(TSection* aSection);		// this method should mark document as changed so that document removes this        // section when saved (e.g. sipAlways)	//------------------------------------------------------------------------------------	// border management	//------------------------------------------------------------------------------------	virtual void DoPostMakeViews(bool forPrinting);		// Calls DoAddBorder for all sections and then calls Inherited::DoPostMakeViews().	virtual void DoAddBorder(TSection* aSection);		// subclasses should override this to create a border to adorn this section	virtual void DoAdjustBorder(TSection* aSection);		// subclasses should override this to adjust the border which adorn this section	virtual void DoDeleteBorder(TSection* aSection);		// subclasses should override this to remove the border adorning this section	virtual bool IsBorderShown(TSection* aSection);		// returns true if (borders are shown) or (the user selection contains aSection)	//------------------------------------------------------------------------------------	// Additional simple accessors	//------------------------------------------------------------------------------------	inline TSectionList* GetSectionList() const { return &const_cast<TEditionDocument*>(this)->fSectionList; }	inline bool GetShowSectionBorders() const { return fShowSectionBorders; }	inline bool GetStopAllEditions() const { return fStopAllEditions; }	inline OSType GetEditionCreatorSignature() const { return fEditionCreator; }		// returns the creator signature used for the edition container file#if qBackwardCompatiblepublic:#elseprotected:#endif	TSectionList fSectionList;					//  list of TSection objects	OSType fEditionCreator;						// creator for publisher edition container file	mutable short fNextEditionNumber;			//  number used in "Untitled-n"	bool fStopAllEditions;						//  false by default	bool fShowSectionBorders;					//  true by default	bool fNewPublishers;						//  are there any new publishers?};//----------------------------------------------------------------------------------------// TNewSubscriberCommand: TNewSubscriberCommand creates a new subscriber and marks the// document as changed.//----------------------------------------------------------------------------------------class EXPORT_MA TNewSubscriberCommand : public TCommand// The TNewSubscriberCommand class implements a command object that// creates a new subscriber.//    MacApp creates a TNewSubscriberCommand object in response// to the user's requests. You seldom need to call or override the// methods of this class. See TCommand for Current information about// command objects.{public:	TNewSubscriberCommand(CommandNumber	itsCommandNumber = cNoCommand,						  TDocument*	itsDocument = NULL);		// constructor	virtual ~TNewSubscriberCommand();		// Destructor			virtual void DoIt();		// Create a new subscriber};//----------------------------------------------------------------------------------------// TSectionBorderCommand: TSectionBorderCommand is an undoable command which changes the setting// for the show/ hide border option for the current document when the user chooses Hide/// Show Borders from the Edit menu//----------------------------------------------------------------------------------------class EXPORT_MA TSectionBorderCommand : public TCommand// The TSectionBorderCommand class implements a command object that// shows or hides the borders of all sections in a document. This// object also changes the value of the fShowSectionBorders field// appropriately. The use of a command object to implement these// tasks allows them to be undone easily.//    MacApp creates a TSectionBorderCommand object in response// to the user's requests. You seldom need to call or override the// methods of this class. See TCommand for Current information about// command objects.{public:	TSectionBorderCommand(CommandNumber	itsCommandNumber = cNoCommand,						  TDocument*	itsDocument = NULL);		// constructor	virtual ~TSectionBorderCommand();		// Destructor			virtual void DoIt();		// tell the document to show or hide the borders for all sections	virtual void UndoIt();		// tell the document to undo show or hide the borders for all sectionsprotected:	bool fShowSectionBorders;				// value to set};//----------------------------------------------------------------------------------------// TStopAllEditionsCommand: TStopAllEditionsCommand is an undoable command gets posted when the// user chooses Stop all Editions from the Edit menu. This command toggles the setting for// the documents fStopAllEditions field.//----------------------------------------------------------------------------------------class EXPORT_MA TStopAllEditionsCommand : public TCommand// The TStopAllEditionsCommand class implements a command object// that stops updates to editions associated with the application's// document. This object also changes the value of the fStopAllEditions// field appropriately. The use of a command object to implement// these tasks allows them to be undone easily.//    MacApp creates a TStopAllEditionsCommand object in response// to the user's requests. You seldom need to call or override the// methods of this class. See TCommand for current information about// command objects.{public:	TStopAllEditionsCommand(CommandNumber	itsCommandNumber = cNoCommand, 							TDocument*		itsDocument = NULL);		// constructor	virtual ~TStopAllEditionsCommand();		// Destructor			virtual void DoIt();		// tell the document to toggle the state of its fStopAllEditions flag	virtual void UndoIt();		// tell the document to toggle the state of its fStopAllEditions flagprotected:	bool fStopAllEditions;					// value to set};//----------------------------------------------------------------------------------------// TSectionAdorner: abstract superclass for section adorners//----------------------------------------------------------------------------------------class EXPORT_MA TSectionAdorner : public TAdorner// TSectionAdorner is an abstract superclass providing some common// initialization and drawing methods for its subclasses, TPublisherAdorner// and TSubscriberAdorner.//    You seldom need to call or override the methods of this class.{	MA_DECLARE_CLONE;	public:	TSectionAdorner(IDType		itsID = kNoIdentifier,					TSection*	itsSection = NULL,					RgnHandle	itsBorderRegion = NULL);		// initializes the section adorner with priority kAdornAfter			virtual ~TSectionAdorner();		// frees fBorderRegion	virtual void InvalidateAdorner(TView* itsView);		// Invalidates the adorner in the TAdornerMgr' TView.	virtual void DrawBorder(const Pattern& whichPattern);			// Draws the adorner's border in the TAdornerMgr' TView.	//------------------------------------------------------------------------------------	// Additional simple accessors	//------------------------------------------------------------------------------------	inline RgnHandle GetBorderRegion() const { return fBorderRegion; }	inline TSection* GetSection() const { return fSection; }#if qBackwardCompatiblepublic:#elseprotected:#endif	CTempRegion_AC fBorderRegion;						// the region for the section border	TSection* fSection;							// the section this adorner adorns};//----------------------------------------------------------------------------------------// TSubscriberAdorner: A specialized adorner for imaging subscriber borders//----------------------------------------------------------------------------------------class EXPORT_MA TSubscriberAdorner : public TSectionAdorner// The TSubscriberAdorner class provides an adorner that is used// to highlight the borders of subscriber sections; that is, the// TSubscriberAdorner::DoHighlightSelection method draws the border// appropriately.//    You normally do not create a subclass of this class. Instead,// you define a TSubscriberAdorner object in the 'View' resource// or instantiate a TSubscriberAdorner object and add that object// to the view. See TAdorner for current information about adorners// and for alternative techniques for creating an adorner.{	MA_DECLARE_CLONE;	public:	TSubscriberAdorner(IDType		itsID = kNoIdentifier,					   TSubscriber*	itsSubscriber = NULL,					   RgnHandle	itsBorderRegion = NULL) :	TSectionAdorner(itsID, itsSubscriber, itsBorderRegion)	{ }	virtual ~TSubscriberAdorner();		// Destructor			virtual void DoHighlightSelection(TView*			itsView,									  const CViewRect&	area,									  HLState			fromHL,									  HLState			toHL);		// Adorns the selection before the view's DoHighlightSelection.};//----------------------------------------------------------------------------------------// TPublisherAdorner//----------------------------------------------------------------------------------------class EXPORT_MA TPublisherAdorner : public TSectionAdorner// The TPublisherAdorner class provides an adorner used to highlight// the border of publishers; that is, the TPublisherAdorner::DoHighlightSelection// method draws the border appropriately.//    You normally do not create a subclass of this class. Instead,// you define a TPublisherAdorner object in the 'View' resource// or instantiate a TPublisherAdorner object and add that object// to the view. See TAdorner for current information about adorners// and for alternative techniques of creating an adorner.{	MA_DECLARE_CLONE;	public:	TPublisherAdorner(IDType		itsID = kNoIdentifier,					  TPublisher*	itsPublisher = NULL,					  RgnHandle		itsBorderRegion = NULL) :	TSectionAdorner(itsID, itsPublisher, itsBorderRegion)	{ }	virtual ~TPublisherAdorner();		// Destructor			virtual void DoHighlightSelection(TView*			itsView,									  const CViewRect&	area,									  HLState			fromHL,									  HLState			toHL);		// Adorns the selection before the view's DoHighlightSelection.};//----------------------------------------------------------------------------------------// TSectionBehavior//----------------------------------------------------------------------------------------class EXPORT_MA TSectionBehavior : public TBehavior// The TSectionBehavior class provides a behavior that implements// a shortcut that displays the Publisher or Subscriber Options// dialog when the user double-clicks a section within one of this// document's views.{	MA_DECLARE_CLONE;	public:	inline TSectionBehavior(IDType itsIdentifier = kNoIdentifier) : TBehavior(itsIdentifier) { }		// constructor	virtual ~TSectionBehavior();		// Destructor			virtual bool DoMouseCommand(CViewPoint&		theMouse,								TToolboxEvent*	event,								CPoint_AC		hysteresis);		// Intercepts mouse commands and traps dbl-clicks in sections.		// By default, calls Inherited.		virtual IDType GetStandardSignature() const;		// Returns this class's standard signature.};//----------------------------------------------------------------------------------------// Externally avaibable routines//----------------------------------------------------------------------------------------EXPORT_MA void InitUEditionDocument();	// call this routine to initialize this unit.#endif/*	Historical Change Record:		----- R11 -----		06/26/96	Install release marker.  Scope many globals.  Change TRUE/FALSE/NULL.		04/30/96	Can't inline TSubscriber/TPublisherAdorner::IFoo b/c we don't have knowledge							that TSubscriber/TPublisher is a TSection in the interface.		04/30/96	Make all constructors use initialization lists if they weren't already							doing do. Switch several more empty constructors to inlines.		04/23/96	Update iterators to be OD stylish.		04/18/96	More Use post-increment with iterators in while loops		----- R10 -----		10/11/95	Add TSectionBehavior::GetStandardSignature.		----- 3.3b1 -----		 3/13/95	Change Free methods to destructors. 		02/22/95	1184041 Change nil to nil*/